CREATE OR REPLACE FUNCTION gf_append_device_timeline() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $body$ DECLARE v_changed_fields text[]; v_event_date date := (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Shanghai')::date; v_event_type varchar(16); v_title varchar(64); v_description varchar(256); BEGIN IF TG_OP = 'INSERT' THEN INSERT INTO device_timelines (device_id, user_id, event_type, event_date, title, description, payload) VALUES (NEW.id, NEW.user_id, 'CREATED', COALESCE(NEW.purchase_date, v_event_date), CASE WHEN NEW.purchase_date IS NULL THEN '添加设备' ELSE '购入设备' END, CASE WHEN NEW.purchase_date IS NULL THEN '设备档案已创建' ELSE '已记录设备购入信息' END, jsonb_build_object('changedFields', ARRAY[]::text[])); RETURN NEW; END IF; IF OLD.deleted_at IS NULL AND NEW.deleted_at IS NOT NULL THEN INSERT INTO device_timelines (device_id, user_id, event_type, event_date, title, description, payload) VALUES (NEW.id, NEW.user_id, 'DISPOSED', COALESCE((NEW.deleted_at AT TIME ZONE 'Asia/Shanghai')::date, v_event_date), '移除设备', '设备已从当前台账中移除', jsonb_build_object('changedFields', ARRAY['deletedAt']::text[])); RETURN NEW; END IF; IF NEW.deleted_at IS NOT NULL THEN RETURN NEW; END IF; v_changed_fields := array_remove(ARRAY[CASE WHEN OLD.category_id IS DISTINCT FROM NEW.category_id THEN 'categoryId' END, CASE WHEN OLD.name IS DISTINCT FROM NEW.name THEN 'name' END, CASE WHEN OLD.status IS DISTINCT FROM NEW.status THEN 'status' END, CASE WHEN OLD.brand IS DISTINCT FROM NEW.brand THEN 'brand' END, CASE WHEN OLD.model IS DISTINCT FROM NEW.model THEN 'model' END, CASE WHEN OLD.serial_number IS DISTINCT FROM NEW.serial_number THEN 'serialNumber' END, CASE WHEN OLD.purchase_date IS DISTINCT FROM NEW.purchase_date THEN 'purchaseDate' END, CASE WHEN OLD.purchase_channel IS DISTINCT FROM NEW.purchase_channel THEN 'purchaseChannel' END, CASE WHEN OLD.purchase_price_cents IS DISTINCT FROM NEW.purchase_price_cents THEN 'purchasePriceCents' END, CASE WHEN OLD.currency IS DISTINCT FROM NEW.currency THEN 'currency' END, CASE WHEN OLD.disposal_date IS DISTINCT FROM NEW.disposal_date THEN 'disposalDate' END, CASE WHEN OLD.disposal_price_cents IS DISTINCT FROM NEW.disposal_price_cents THEN 'disposalPriceCents' END, CASE WHEN OLD.notes IS DISTINCT FROM NEW.notes THEN 'notes' END], NULL); IF cardinality(v_changed_fields) > 0 THEN IF OLD.status IS DISTINCT FROM NEW.status AND NEW.status IN ('SOLD', 'DISCARDED') THEN v_event_type := 'DISPOSED'; v_title := CASE WHEN NEW.status = 'SOLD' THEN '出售设备' ELSE '报废设备' END; v_description := '设备处置状态已更新'; ELSE v_event_type := 'UPDATED'; v_title := '更新设备'; v_description := '设备档案已更新'; END IF; INSERT INTO device_timelines (device_id, user_id, event_type, event_date, title, description, payload) VALUES (NEW.id, NEW.user_id, v_event_type, v_event_date, v_title, v_description, jsonb_build_object('changedFields', v_changed_fields)); END IF; RETURN NEW; END $body$;
